12		"github.com/anthnel/devdesk/internal/ui/theme"
13	)
14	
15	const (
16		// noModel stands for an agent whose transcript named no model.
17		noModel = "-"
18		// unknownType stands for a sub-agent whose meta file gave no type.
19		unknownType = "unknown"
20		// orchestratorLabel is the Agent cell of the main agent.
21		orchestratorLabel = "orchestrator"
22		// partialMark prefixes an output count that is a floor, not an exact value.
23		partialMark = "≥ "
24		// stem and lastStem draw the tree branch in front of a sub-agent's type.
25		stem     = "├─ "
26		lastStem = "└─ "
27	)
28	
29	// agentIDPrefix is the shortest agent ID shown.
30	const agentIDPrefix = 8
31	
32	// agentRow is one line of the agents table.
33	type agentRow struct {
34		agentusage.Agent
35		branch  string // stem, lastStem, or "" (orchestrator, or a sorted list)
36		shortID string // ID prefix, distinct within the session; "" for the orchestrator
37		share   int    // tenths of a percent of the session total, or noShare
38	}
39	
40	// agentRows orders a session's agents (orchestrator, then sub-agents by ID),
41	// gives each its short ID and share, and draws the branches when tree is true.
42	// The sort is stable so equal IDs keep their input order.
43	func agentRows(u agentusage.Usage, tree bool) []agentRow {
44		var main, subs []agentusage.Agent
45		for _, a := range u.Agents {
46			if a.Main {
47				main = append(main, a)
48			} else {
49				subs = append(subs, a)
50			}
51		}
52		sort.SliceStable(subs, func(i, j int) bool { return subs[i].ID < subs[j].ID })
53	
54		ordered := append(append([]agentusage.Agent{}, main...), subs...)
55		totals := make([]int64, len(ordered))
56		for i, a := range ordered {
57			totals[i] = a.Tokens.Total()
58		}
59		mainIdx := -1
60		if len(main) > 0 {
61			mainIdx = 0
62		}
63		parts := shares(totals, u.Total().Total(), mainIdx)
64	
65		ids := make([]string, len(subs))
66		for i, a := range subs {
67			ids[i] = a.ID
68		}
69		short := shortAgentIDs(ids)
70	
71		rows := make([]agentRow, 0, len(ordered))
72		for i, a := range ordered {
73			row := agentRow{Agent: a, share: parts[i]}
74			if !a.Main {
75				j := i - len(main)
76				row.shortID = short[j]
77				if tree {
78					row.branch = stem
79					if j == len(subs)-1 {
80						row.branch = lastStem
81					}
82				}
83			}
84			rows = append(rows, row)
85		}
86		return rows
87	}
88	
89	// shortAgentIDs cuts every ID to one common length, the smallest n >=
90	// agentIDPrefix (in runes) at which all of them differ, capped at each ID's
91	// own length.
92	func shortAgentIDs(ids []string) []string {
93		if len(ids) == 0 {
94			return nil
95		}
96		longest := 0
97		runes := make([][]rune, len(ids))
98		for i, id := range ids {
99			runes[i] = []rune(id)
100			longest = max(longest, len(runes[i]))
101		}
102		cut := func(n int) []string {
103			out := make([]string, len(runes))
104			for i, r := range runes {
105				out[i] = string(r[:min(n, len(r))])
106			}
107			return out
108		}
109		for n := agentIDPrefix; n < longest; n++ {
110			seen := make(map[string]bool, len(ids))
111			distinct := true
112			for _, s := range cut(n) {
113				if seen[s] {
114					distinct = false
115					break
116				}
117				seen[s] = true
118			}
119			if distinct {
120				return cut(n)
121			}
122		}
123		return cut(longest)
124	}
125	
126	// agentColumns describes the agents table. Nothing sorts: the order is the
127	// tree. Cache columns give way first on a narrow terminal, writes before reads.
128	func agentColumns() []datatable.Column[agentRow] {
129		count := func(title string, width int, tokens func(agentRow) int64) datatable.Column[agentRow] {
130			return datatable.Column[agentRow]{
131				Title: title, Sizing: datatable.SizingFixed, MinWidth: width,
132				Cell:  func(r agentRow) string { return formatTokens(tokens(r)) },
133				Style: func(r agentRow) lipgloss.Style { return dimWhen(tokens(r) == 0) },
134			}
135		}
136		in := count("In", 6, func(r agentRow) int64 { return r.Tokens.Input })
137		cacheRead := count("Cache read", len("Cache read"), func(r agentRow) int64 { return r.Tokens.CacheRead })
138		cacheRead.Optional = true
139		cacheWrite := count("Cache write", len("Cache write"), func(r agentRow) int64 { return r.Tokens.CacheWrite })
140		cacheWrite.Optional, cacheWrite.DropFirst = true, true
141		total := count("Total", 6, func(r agentRow) int64 { return r.Tokens.Total() })
142	
143		out := count("Out", 7, nil)
144		out.Cell = outCell
145		out.Style = func(r agentRow) lipgloss.Style { return dimWhen(r.Tokens.Output == 0) }
146	
147		return []datatable.Column[agentRow]{
148			{Title: "Agent", Sizing: datatable.SizingContent, MinWidth: 14, Cell: roleCell, Search: agentSearch,
149				Style: func(r agentRow) lipgloss.Style { return dimWhen(!r.Main && r.Type == "") }},
150			{Title: "Model", Sizing: datatable.SizingContent, MinWidth: 12, Flex: 2, Cell: modelsCell, Search: modelsCell,
151				Style: func(r agentRow) lipgloss.Style { return dimWhen(len(r.Models) == 0) }},
152			in, out, cacheRead, cacheWrite, total,
153		}
154	}
155	
156	// dimWhen is Rule 122's colour discipline: a zero or a placeholder is dim,
157	// anything else keeps the default colour.
158	func dimWhen(dim bool) lipgloss.Style {
159		if dim {
160			return theme.DimStyle
161		}
162		return lipgloss.NewStyle()
163	}
164	
165	// agentSearch is what `/` matches in the Agent column: the role and the ID,
166	// which no column shows.
167	func agentSearch(r agentRow) string { return roleCell(r) + " " + r.ID }
168	
169	// roleCell is the Agent cell: "orchestrator", or the sub-agent's type behind
170	// its branch.
171	func roleCell(r agentRow) string {
172		if r.Main {
173			return orchestratorLabel
174		}
175		typ := r.Type
176		if typ == "" {
177			typ = unknownType
178		}
179		return r.branch + typ
180	}
181	
182	// modelsCell lists the models the agent used.
183	func modelsCell(r agentRow) string {
184		if len(r.Models) == 0 {
185			return noModel
186		}
187		return strings.Join(r.Models, ", ")
188	}
189	
190	// outCell is the output count. A sub-agent still being written is a floor and
191	// says so; the orchestrator never does, its transcript is the one being read.
192	func outCell(r agentRow) string {
193		out := formatTokens(r.Tokens.Output)
194		if !r.Main && r.PartialOutput() {
195			return partialMark + out
196		}
197		return out
198	}
199	
200	// formatTokens renders a count compactly, floored to one decimal: 1099 is
201	// "1.0k", never "1.1k". From 100 of a unit up the decimal is dropped.
202	func formatTokens(n int64) string {
203		units := []struct {
204			size   int64
205			suffix string
206		}{
207			{1_000_000_000_000, "T"}, {1_000_000_000, "B"}, {1_000_000, "M"}, {1_000, "k"},
208		}
209		for _, u := range units {
210			if n < u.size {
211				continue
212			}
213			tenths := n / (u.size / 10) // divide first: n*10 would overflow
214			if tenths >= 1000 {
215				return fmt.Sprintf("%d%s", tenths/10, u.suffix)
216			}
217			return fmt.Sprintf("%d.%d%s", tenths/10, tenths%10, u.suffix)
218		}
219		return fmt.Sprintf("%d", n)
220	}
