1	package agentusageview
2	
3	import (
4		"fmt"
5		"math/bits"
6	)
7	
8	const (
9		// shareScale is a share's precision: tenths of a percent.
10		shareScale = 1000
11		// noShare marks a share that cannot be computed: the session has no tokens.
12		noShare = -1
13	)
14	
15	// shares returns each total's part of the session total in tenths of a
16	// percent, floored. The entry at mainIdx takes the rounding residue so the
17	// parts add up to shareScale; mainIdx < 0 leaves every part floored. A zero
18	// total yields noShare everywhere.
19	func shares(totals []int64, total int64, mainIdx int) []int {
20		out := make([]int, len(totals))
21		if total <= 0 {
22			for i := range out {
23				out[i] = noShare
24			}
25			return out
26		}
27		rest := shareScale
28		for i, t := range totals {
29			out[i] = floorTenths(t, total)
30			if i != mainIdx {
31				rest -= out[i]
32			}
33		}
34		if mainIdx >= 0 && mainIdx < len(out) {
35			out[mainIdx] = max(rest, 0) // clamped: saturated totals can overshoot
36		}
37		return out
38	}
39	
40	// floorTenths is floor(part*shareScale/total) on 128 bits, so no product
41	// overflows. part is clamped to [0, total]; total > 0.
42	func floorTenths(part, total int64) int {
43		part = min(max(part, 0), total)
44		hi, lo := bits.Mul64(uint64(part), shareScale)
45		q, _ := bits.Div64(hi, lo, uint64(total)) // hi < total because part <= total
46		return int(q)
47	}
48	
49	// formatShare renders tenths of a percent: 123 is "12.3%"; noShare is "-".
50	func formatShare(tenths int) string {
51		if tenths < 0 {
52			return noModel
53		}
54		return fmt.Sprintf("%d.%d%%", tenths/10, tenths%10)
55	}
