113	// breadcrumb is Sessions › project › ID, the last one active and its parents
114	// dim, with the one cell of left padding Rule 123 asks for.
115	func (m Model) breadcrumb(width int) string {
116		project := noProject
117		if m.open.Project != "" {
118			project = theme.ShortPath(m.open.Project, max(width/2, 1))
119		}
120		base := lipgloss.NewStyle().Background(theme.ColorBackground)
121		parents := base.Foreground(theme.ColorDim).Render("Sessions › " + project + " › ")
122		active := base.Foreground(theme.ColorSecondary).Bold(true).Render(shortID(m.open.ID))
123		return theme.PadWithBg(theme.Bg(" ")+parents+active, width)
124	}
