126	// status is derived on every frame, with no timer (Rule 128).
127	//
128	// The empty sentence needs the listing to be empty in total, not after the
129	// filter: a filter with no match is not a machine with no sessions.
130	func (m Model) status() sharedcomponents.Status {
131		if m.level == levelAgents {
132			return m.agentsStatus()
133		}
134		switch {
135		case m.loadErr:
136			return sharedcomponents.Status{
137				Text:  "Failed to list Claude Code sessions — check logs",
138				Level: sharedcomponents.LevelError,
139			}
